def levenshtein(s1, s2):
    if len(s1) < len(s2):
        return levenshtein(s2, s1)
    # len(s1) >= len(s2)
    prev_row = [i for i in range(len(s2) + 1)]
    for i in range(1, len(s1) + 1):
        current_row = [0] * (len(s2) + 1)
        current_row[0] = i
        for j in range(1, len(s2) + 1):
            cost = 0 if s1[i-1] == s2[j-1] else 1
            current_row[j] = min(
                current_row[j-1] + 1,  # insert
                prev_row[j] + 1,      # delete
                prev_row[j-1] + cost  # substitute
            )
        prev_row = current_row
    return prev_row[-1]

def find_closest_match(query, names):
    if not names:
        return None
    best_name = None
    best_score = -1.0
    for name in names:
        distance = levenshtein(query, name)
        max_len = max(len(query), len(name))
        similarity = 1.0 - (distance / max_len)
        if similarity > best_score:
            best_score = similarity
            best_name = name
    return best_name

