import time
from functools import wraps

def cache_with_ttl(ttl_seconds):
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate a hashable key based on arguments
            key = (args, tuple(sorted(kwargs.items())))

            # Check if the key exists in the cache
            if key in cache:
                current_time = time.time()
                if current_time < cache[key][1]:
                    # Result is still valid
                    return cache[key][0]
                else:
                    # Remove expired entry
                    del cache[key]

            # Compute the result
            result = func(*args, **kwargs)
            # Store the result with expiration time
            cache[key] = (result, time.time() + ttl_seconds)
            return result

        return wrapper

    return decorator

import phonenumbers

def format_phone_number(number: str) -> str:
    """
    Validate and format a phone number into international format.

    Args:
        number (str): The phone number as a string (e.g., "1234567890", "+1234567890", "123-456-7890").

    Returns:
        str: The phone number in international format (e.g., "+1 123 456 7890").
    """
    try:
        # Parse the number, allowing the library to infer the country code
        parsed = phonenumbers.parse(number, None)
        if phonenumbers.is_valid_number(parsed):
            return phonenumbers.format_number(parsed, phonenumbers.PhoneNumberFormat.INTERNATIONAL)
        else:
            return "Invalid number"
    except Exception as e:
        return f"Invalid number: {str(e)}"

def levenshtein(s1: str, s2: str) -> int:
    """
    Compute the Levenshtein distance between two strings.
    """
    if len(s1) < len(s2):
        return levenshtein(s2, s1)

    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and column
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],  # Deletion
                    dp[i][j - 1],  # Insertion
                    dp[i - 1][j - 1]  # Substitution
                )

    return dp[n][m]


