def get_env_value(key: str, default: str) -> str:
    """
    Read a value from a .env file, or return a default if the key is not found.

    Args:
        key (str): The key to look for in the .env file.
        default (str): The default value to return if the key is not found.

    Returns:
        str: The value associated with the key, or the default.
    """
    try:
        with open('.env', 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    if k == key:
                        return v
    except FileNotFoundError:
        pass
    return default
